using System;using System.IO;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;
namespace FashionFit {
 public static class SurfacePolishScenario {
  [Serializable]public sealed class Result{public string status="passed",scope="Real menu/near Grip routes, injected Touch and manually stepped solver; no physical headset";public int checks,exceptions,contacts,shirtVertices,shirtTriangles,shirtComponents,boundaryLoops,hatSeamVertices;public bool connectedShirt,hatSeam,cabinetJoin,readoutStaysVisible,readoutUnits,cache;public float cottonTravelM,stretchTravelM,peakStrain;public double cachedMeshMs;}
  static FashionFitApp app;static RunwayVRHands hands;static Result result;static string folder;
  static void Check(bool ok,string message){result.checks++;if(!ok)throw new Exception(message);}static void Log(string a,string b,LogType t){if(t==LogType.Error||t==LogType.Exception)result.exceptions++;}
  public static Result Run(FashionFitApp owner,string output){app=owner;folder=output;Directory.CreateDirectory(folder+"/Contact");result=new Result();var mode=Physics.simulationMode;Application.logMessageReceived+=Log;try{Physics.simulationMode=SimulationMode.Script;app.Player.PrepareForVRTrial();app.Player.EnsureHands();hands=app.Player.Hands;app.Player.PreviewVRMenu();typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,true);typeof(RunwayPlayer).GetProperty("HeadTracked").SetValue(app.Player,true);app.PoseStudio.SetHandles(false);app.MaterialLab.ShowReadings=false;
   var avatar=app.PoseStudio.Rigs[0].Avatar;result.cache=Resources.Load<Mesh>("ContinuousShirts/"+ContinuousShirtShell.CacheKey(avatar,false));Check(result.cache,"Missing body/rig-specific shirt cache");var timer=System.Diagnostics.Stopwatch.StartNew();var raw=ContinuousShirtShell.Build(avatar,false);timer.Stop();result.cachedMeshMs=timer.Elapsed.TotalMilliseconds;Topology(raw);UnityEngine.Object.DestroyImmediate(raw);
   var hat=app.Showroom.Hats[2];hat.ReturnToDisplay();var hm=hat.Elastic.MeshAt(0);var hv=hm.vertices;var ht=hm.triangles;for(int i=0;i<hv.Length;i++){var p=hv[i];if(Mathf.Abs(p.y)>.00002f||Mathf.Abs(p.x*p.x/(.101f*.101f)+p.z*p.z/(.119f*.119f)-1)>.0005f)continue;bool crown=false,brim=false;for(int k=0;k<ht.Length;k+=3)if(ht[k]==i||ht[k+1]==i||ht[k+2]==i){float y=(hv[ht[k]].y+hv[ht[k+1]].y+hv[ht[k+2]].y)/3;if(y>.002f)crown=true;else if(y<.0001f)brim=true;}if(crown&&brim)result.hatSeamVertices++;}result.hatSeam=result.hatSeamVertices>=60;Check(result.hatSeam,"Hat crown and brim still use disconnected/gapped borders");
   var plinth=app.Showroom.transform.Find("Wardrobe stone plinth").GetComponent<Renderer>().bounds;var floor=app.transform.Find("Fashion Unity atelier - 8m x 8m/Floor").GetComponent<Renderer>().bounds;result.cabinetJoin=plinth.min.y<=floor.max.y+.001f;foreach(string name in new[]{"Wardrobe left","Wardrobe right","Wardrobe back"})result.cabinetJoin&=Mathf.Abs(app.Showroom.transform.Find(name).GetComponent<Renderer>().bounds.min.y-plinth.max.y)<.0001f;Check(result.cabinetJoin,"Cabinet panels/plinth/floor do not meet");
   for(int gender=0;gender<2;gender++){app.Showroom.SelectOutfitTarget(gender+1);app.PoseStudio.Wear(gender,5);var wear=app.PoseStudio.Wearables[gender];wear.SetMaterial(MembraneMaterial.Presets[0]);for(int i=0;i<30;i++)wear.Step(1f/60);Export(wear,gender+"_Neutral");if(gender==0){CaptureAvatar(wear,"IvoryFront.png",new Vector3(.55f,1.35f,1.8f));CaptureAvatar(wear,"IvorySide.png",new Vector3(.9f,1.35f,.30f));}
    var menu=app.Player.VRMenu;menu.Show();menu.SelectPage(8);menu.ActionButtons[3].Activate();Check(menu.Page==12,"Material detail route does not open readout");var surface=wear.Surface;var points=surface.MeshAt(0).vertices;int index=Closest(points,new Vector3(-.10f,1.28f,.23f));Vector3 p=surface.transform.TransformPoint(points[index]);Grip(p);result.readoutStaysVisible=menu.Visible&&hands.HeldBy(0)&&hands.HeldBy(0).Elastic==surface;Check(result.readoutStaysVisible,"Instrument hides or blocks near fabric Grip");for(int i=0;i<90;i++){hands.Step(0,true,p+Vector3.forward*.30f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}float travel=Vector3.Distance(points[index],surface.MeshAt(0).vertices[index]);Check(Mathf.Abs(surface.RequestedTravelM-.30f)<.002f&&Mathf.Abs(surface.AppliedTravelM-.05f)<.002f,"Readout confuses requested hand movement and clamped command");Check(travel>.02f&&travel<.075f,"Continuous shirt has no bounded pull response");if(gender==0)result.cottonTravelM=travel;Export(wear,gender+"_Pulled");menu.Refresh();string readout=app.MaterialLab.DetailedReadout;result.readoutUnits=readout.Contains("N/m")&&readout.Contains("kPa")&&readout.Contains("g/m²")&&readout.Contains("CHƯA HIỆU CHUẨN")&&readout.Contains("95%");Check(result.readoutUnits,"Missing force/strain/unit/calibration labels");var text=FindReadout(menu);Check(text&&text.GetComponent<Renderer>().localBounds.size.x<.97f&&text.GetComponent<Renderer>().localBounds.size.y<.30f,"Instrument text overflows panel");if(gender==0){CaptureMenu(menu,"CottonReadout.png");if(!app.MaterialLab.HatMode)app.MaterialLab.ToggleFocus();menu.ActionButtons[4].Activate();Check(surface.Material==MembraneMaterial.Presets[1],"Readout material button edits hat instead of held fabric");Check(app.MaterialLab.ProfileLabel==surface.Material.label,"Readout title differs from held material");app.MaterialLab.SelectProfile(0);if(app.MaterialLab.HatMode)app.MaterialLab.ToggleFocus();}hands.ReleaseAll(false);for(int i=0;i<330;i++)wear.Step(1f/60);Export(wear,gender+"_Recovered");
    app.PoseStudio.SetHandles(true);RunwayPoseHandle handle=null;foreach(var h in wear.Rig.Handles)if(h.Bone.name=="LeftHand"){handle=h;break;}Check(handle,"No wrist pose handle");Vector3 hp=handle.transform.position;Grip(hp);Check(hands.HeldBy(0)&&hands.HeldBy(0).IsJoint,"Cannot pose in new shirt");for(int i=0;i<70;i++){hands.Step(0,true,hp+Vector3.up*.10f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}Export(wear,gender+"_Posed");hands.ReleaseAll(false);app.PoseStudio.ResetPose(gender);app.PoseStudio.SetHandles(false);
    if(gender==0){surface.SetMaterial(MembraneMaterial.Presets[1]);surface.ResetShape();wear.Step(1f/60);points=surface.MeshAt(0).vertices;index=Closest(points,new Vector3(-.1f,1.28f,.23f));p=surface.transform.TransformPoint(points[index]);menu.Show();menu.SelectPage(12);Grip(p);for(int i=0;i<100;i++){hands.Step(0,true,p+Vector3.forward*.30f,Quaternion.identity,1,0,1f/60);wear.Step(1f/60);}result.stretchTravelM=Vector3.Distance(points[index],surface.MeshAt(0).vertices[index]);Check(surface.AppliedTravelM>.099f&&result.stretchTravelM>result.cottonTravelM*1.4f,"10 cm material cap does not differ from 5 cm");result.peakStrain=surface.Reading.peakTensileStrain;Check(surface.Reading.peakTensileStrain+1e-6f>=surface.Reading.tensileStrain,"Peak strain is smaller than RMS");menu.Refresh();CaptureMenu(menu,"StretchReadout.png");hands.ReleaseAll(false);}
   }
   app.Player.VRMenu.Hide();hands.Hide();Capture(app.Player.View,new Vector3(-.10f,.28f,-.92f),new Vector3(-.47f,.10f,-1.62f),"CabinetCorner.png");Capture(app.Player.View,hat.transform.TransformPoint(new Vector3(.34f,.11f,.31f)),hat.transform.TransformPoint(new Vector3(0,.025f,0)),"HatJoin.png");Check(result.exceptions==0,"Unity errors during surface/readout scenario");
  }catch(Exception e){result.status="failed";File.WriteAllText(folder+"/failure.txt",e.ToString());throw;}finally{hands?.ReleaseAll(false);typeof(RunwayPlayer).GetProperty("InVR").SetValue(app.Player,false);Physics.simulationMode=mode;Application.logMessageReceived-=Log;File.WriteAllText(folder+"/verification.json",JsonUtility.ToJson(result,true));}return result;}
  static TextMesh FindReadout(RunwayVRPanel menu){foreach(var t in menu.GetComponentsInChildren<TextMesh>())if(t.text.Contains("F lệnh ảo"))return t;return null;}
  static int Closest(Vector3[] points,Vector3 target){int best=0;float distance=float.PositiveInfinity;for(int i=0;i<points.Length;i++){float d=(points[i]-target).sqrMagnitude;if(d<distance){distance=d;best=i;}}return best;}
  static void Grip(Vector3 p){Physics.SyncTransforms();hands.Step(0,true,p,Quaternion.identity,0,0,1f/60);hands.Step(0,true,p,Quaternion.identity,1,0,1f/60);}
  static void Topology(Mesh mesh){result.shirtVertices=mesh.vertexCount;result.shirtTriangles=mesh.triangles.Length/3;var edges=new Dictionary<long,int>();var graph=new Dictionary<int,List<int>>();var faces=mesh.triangles;for(int i=0;i<faces.Length;i+=3)for(int k=0;k<3;k++){int a=faces[i+k],b=faces[i+(k+1)%3];long key=((long)Mathf.Min(a,b)<<32)|(uint)Mathf.Max(a,b);edges[key]=edges.TryGetValue(key,out int n)?n+1:1;}bool manifold=true;foreach(var e in edges){manifold&=e.Value<=2;if(e.Value!=1)continue;int a=(int)(e.Key>>32),b=(int)e.Key;if(!graph.ContainsKey(a))graph[a]=new List<int>();if(!graph.ContainsKey(b))graph[b]=new List<int>();graph[a].Add(b);graph[b].Add(a);}Check(manifold,"Non-manifold shirt edge");bool simpleBorders=true;var pending=new HashSet<int>(graph.Keys);while(pending.Count>0){var iterator=pending.GetEnumerator();iterator.MoveNext();int first=iterator.Current;pending.Remove(first);var stack=new Stack<int>();stack.Push(first);while(stack.Count>0){int a=stack.Pop();simpleBorders&=graph[a].Count==2;foreach(int b in graph[a])if(pending.Remove(b))stack.Push(b);}result.boundaryLoops++;}Check(simpleBorders,"Cracked or branching shirt border");var parent=new int[mesh.vertexCount];for(int i=0;i<parent.Length;i++)parent[i]=i;int Find(int i){while(parent[i]!=i){parent[i]=parent[parent[i]];i=parent[i];}return i;}for(int i=0;i<faces.Length;i+=3){parent[Find(faces[i+1])]=Find(faces[i]);parent[Find(faces[i+2])]=Find(faces[i]);}var components=new HashSet<int>();foreach(int index in faces)components.Add(Find(index));result.shirtComponents=components.Count;Check(result.shirtComponents==1,"Disconnected torso and sleeves");result.connectedShirt=result.boundaryLoops==4;Check(result.connectedShirt,"Expected only neck, hem and two cuff openings; found "+result.boundaryLoops);}
  static void Export(PoseWearable wear,string name){var avatar=wear.Rig.Avatar;var body=new Mesh();var old=avatar.Renderer.sharedMesh;avatar.Renderer.sharedMesh=avatar.BodyMesh;avatar.Renderer.BakeMesh(body);avatar.Renderer.sharedMesh=old;using(var writer=new BinaryWriter(File.Create(folder+"/Contact/"+name+".bin"))){writer.Write(0x53434631);Write(writer,body.vertices,body.triangles);Write(writer,wear.Surface.MeshAt(0).vertices,wear.Surface.MeshAt(0).triangles);}UnityEngine.Object.DestroyImmediate(body);result.contacts++;}
  static void Write(BinaryWriter w,Vector3[] points,int[] faces){w.Write(points.Length);foreach(var p in points){w.Write(p.x);w.Write(p.y);w.Write(p.z);}w.Write(faces.Length);foreach(int i in faces)w.Write(i);}
  static void CaptureAvatar(PoseWearable wear,string name,Vector3 point){var root=wear.Rig.Avatar.transform;Capture(app.Player.View,root.TransformPoint(point),root.TransformPoint(new Vector3(0,1.22f,0)),name);}
  static void CaptureMenu(RunwayVRPanel menu,string name){var renderers=hands.GetComponentsInChildren<Renderer>();var old=new bool[renderers.Length];for(int i=0;i<renderers.Length;i++){old[i]=renderers[i].enabled;renderers[i].enabled=false;}try{Capture(app.Player.View,menu.transform.position-menu.transform.forward*1.17f,menu.transform.position,name);}finally{for(int i=0;i<renderers.Length;i++)renderers[i].enabled=old[i];}}
  static void Capture(Camera c,Vector3 point,Vector3 target,string name){c.rect=new Rect(0,0,1,1);c.transform.position=point;c.transform.LookAt(target,Vector3.up);var rt=new RenderTexture(1400,1100,24);var image=new Texture2D(1400,1100,TextureFormat.RGB24,false);var old=RenderTexture.active;try{c.targetTexture=rt;c.Render();RenderTexture.active=rt;image.ReadPixels(new Rect(0,0,1400,1100),0,0);image.Apply();File.WriteAllBytes(folder+"/"+name,image.EncodeToPNG());}finally{c.targetTexture=null;RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(image);UnityEngine.Object.DestroyImmediate(rt);}}
 }
 public sealed class SurfacePolishPlayerVerification:MonoBehaviour {
  string folder;[RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){var args=Environment.GetCommandLineArgs();for(int i=0;i<args.Length-1;i++)if(args[i]=="-fashionSurfaceVerify"){var test=new GameObject("Explicit surface and readout QA").AddComponent<SurfacePolishPlayerVerification>();test.folder=args[i+1];break;}}
  IEnumerator Start(){Application.runInBackground=true;FashionFitApp app=null;double deadline=Time.realtimeSinceStartupAsDouble+40;while(!app||!app.Ready){app=FindObjectOfType<FashionFitApp>();if(Time.realtimeSinceStartupAsDouble>deadline){Application.Quit(1);yield break;}yield return null;}int code=0;try{SurfacePolishScenario.Run(app,folder);}catch(Exception e){Debug.LogException(e);code=1;}Application.Quit(code);}
 }
}
